// Pixel-perfect checkerboard: each square is exactly uSquarePx layer pixels.
// Every 4th square along each row/column (diagonal cadence) is highlighted.
uniform int   uSquarePx;   // @param 8 1 256
uniform vec3  uColorA;     // @param #1A1A1E
uniform vec3  uColorB;     // @param #E6E6E6
uniform vec3  uHighlight;  // @param #FF6B1A

void main() {
  int n = max(uSquarePx, 1);
  // Integer pixel coordinate within the layer (pixel centers -> exact ints).
  ivec2 px = ivec2(floor(uv * iResolution));
  // Flip Y so square 0,0 is anchored at the top-left of the layer.
  px.y = int(iResolution.y) - 1 - px.y;
  ivec2 cell = px / n;  // px is non-negative, so integer division == floor

  int parity = (cell.x + cell.y) & 1;
  vec3 col = parity == 0 ? uColorA : uColorB;

  // Every 4th square: walking along any row or column, squares 0,4,8,... highlight.
  if (((cell.x + cell.y) & 3) == 0) col = uHighlight;

  fragColor = vec4(col, 1.0);
}
